  d2 *= 0.6;
  float d0 = d1;
  vec3 c0 = c1;
  if (d0 >= INF * 0.5) c0 = c2; else if (d2 < INF * 0.5) c0 = mix(c2, c0, clamp(0.5 + 0.5 * (d2 - d0) / max((x_Blend), 1e-4), 0.0, 1.0));
